<?php namespace App\Models; use Illuminate\Database\Eloquent\Model; use Illuminate\Database\Eloquent\SoftDeletes; class SeoKeyword extends Model { use SoftDeletes; protected $fillable=['seo_campaign_id','keyword','normalized_keyword','target_page_url','category','search_intent','location','language','device','search_engine','search_volume','keyword_difficulty','priority','remarks','created_by']; public function campaign(){return $this->belongsTo(SeoCampaign::class,'seo_campaign_id');} public function rankings(){return $this->hasMany(SeoKeywordRanking::class);} public function latestRanking(){return $this->hasOne(SeoKeywordRanking::class)->latestOfMany('checked_on');} }
